export type Job<T> = () => Promise<T> | T;

export class JobQueue {
  private readonly concurrency: number;
  private readonly maxRetries: number;
  private readonly pending: Array<() => Promise<void>> = [];
  private idleWaiters: Array<() => void> = [];
  private active = 0;

  constructor(concurrency: number, maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    if (!Number.isInteger(maxRetries) || maxRetries < 0) {
      throw new RangeError("maxRetries must be a non-negative integer");
    }
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
  }

  /** Number of jobs waiting to start. */
  get size(): number {
    return this.pending.length;
  }

  /** Number of jobs currently running. */
  get running(): number {
    return this.active;
  }

  /**
   * Enqueue a job. The returned promise settles with the job's result, or
   * rejects with the last error once every retry has failed.
   */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.attempt(job));
        } catch (err) {
          reject(err);
        }
      });
      this.drain();
    });
  }

  /** Resolves once nothing is queued or running. Failed jobs do not reject it. */
  onIdle(): Promise<void> {
    if (this.active === 0 && this.pending.length === 0) {
      return Promise.resolve();
    }
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    for (let retries = 0; ; retries++) {
      try {
        return await job();
      } catch (err) {
        if (retries >= this.maxRetries) throw err;
      }
    }
  }

  private drain(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.active++;
      void run().finally(() => {
        this.active--;
        this.drain();
      });
    }

    if (this.active === 0 && this.pending.length === 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }
}

