import { JobQueue } from "./jobQueue.ts";
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const q = new JobQueue(2);
let cur = 0, peak = 0, flaky = 0, dead = 0;
const results = [];
for (let i = 0; i < 6; i++) q.add(async () => { cur++; peak = Math.max(peak, cur); await sleep(20); cur--; return i; }).then(v => results.push(v));
const f = q.add(async () => { if (++flaky < 3) throw new Error("flaky"); return "ok"; });
const d = q.add(() => { dead++; throw new Error("always"); }).catch(e => "rejected: " + e.message);
await q.onIdle();
console.log({ peak, results, flaky, flakyResult: await f, dead, deadResult: await d, size: q.size, running: q.running });
await q.onIdle(); console.log("idle on empty queue ok");
